//! Writes the reference merge fixture of controller/internal/metrics.
use fps_stats::{metric, SeriesValue, Shard, Snapshot, SnapshotMeta, Timestamp};
use serde_json::{json, Value};

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn latency(&mut self) -> u64 {
        // Spread values over several orders of magnitude.
        let mag = self.next() % 7;
        let base = 10u64.pow(mag as u32);
        1 + self.next() % (base * 9)
    }
}

fn fill(shard: &mut Shard, rng: &mut Rng, scale: u64) {
    let web = [("application", "http1"), ("scenario", "web_get")];
    let dns = [("application", "dns"), ("scenario", "query")];
    for labels in [&web[..], &dns[..]] {
        let att = shard.counter(metric::SESSIONS_ATTEMPTED, labels).unwrap();
        let ok = shard.counter(metric::SESSIONS_SUCCEEDED, labels).unwrap();
        let tx = shard.counter(metric::BYTES_TX, labels).unwrap();
        let conc = shard.gauge(metric::SESSIONS_CONCURRENT, labels).unwrap();
        let rt = shard.histogram(metric::SESSIONS_RESPONSE_TIME, labels).unwrap();
        let n = 200 * scale + rng.next() % 100;
        shard.add(att, n);
        shard.add(ok, n - n / 10);
        shard.add(tx, n * 1234);
        shard.set(conc, (rng.next() % 50) as f64);
        for _ in 0..n {
            let v = rng.latency();
            shard.record(rt, v);
        }
        let mut fl = labels.to_vec();
        fl.push(("reason", "expect_timeout"));
        let failed = shard.counter(metric::SESSIONS_FAILED, &fl).unwrap();
        shard.add(failed, n / 20);
        fl.pop();
        fl.push(("reason", "connect_refused"));
        let failed = shard.counter(metric::SESSIONS_FAILED, &fl).unwrap();
        shard.add(failed, n / 20);
    }
    let port = [("port", "p1")];
    let rtt = shard.histogram(metric::TCP_RTT, &port).unwrap();
    let hs = shard.counter(metric::TCP_HANDSHAKES, &port).unwrap();
    shard.add(hs, 77 * scale);
    for _ in 0..(50 * scale) {
        let v = rng.latency();
        shard.record(rtt, v);
    }
}

fn hist_json(s: &Snapshot) -> Vec<Value> {
    let mut out = Vec::new();
    for (key, value) in s.iter() {
        let SeriesValue::Histogram(h) = value else { continue };
        let labels: serde_json::Map<String, Value> = key
            .labels()
            .iter()
            .map(|(k, v)| ((*k).to_owned(), Value::from(v.as_str())))
            .collect();
        let buckets: Vec<Value> = h
            .iter_recorded()
            .map(|v| json!([v.value_iterated_to().to_string(), v.count_at_value().to_string()]))
            .collect();
        out.push(json!({
            "metric": key.metric().name(),
            "labels": labels,
            "count": h.len().to_string(),
            "min": h.min().to_string(),
            "max": h.max().to_string(),
            "mean": h.mean(),
            "p50": h.value_at_quantile(0.5).to_string(),
            "p90": h.value_at_quantile(0.9).to_string(),
            "p99": h.value_at_quantile(0.99).to_string(),
            "p999": h.value_at_quantile(0.999).to_string(),
            "buckets": buckets,
        }));
    }
    out
}

fn main() {
    let mut rng = Rng(42);
    let mut a0 = Shard::new(0);
    let mut a1 = Shard::new(1);
    let mut b1 = Shard::new(1);
    let mut b2 = Shard::new(2);
    fill(&mut a0, &mut rng, 1);
    fill(&mut a1, &mut rng, 2);
    fill(&mut b1, &mut rng, 3);
    fill(&mut b2, &mut rng, 1);
    let agg_a = Snapshot::merge_all([&a0.snapshot(), &a1.snapshot()]).unwrap();
    let w1 = b1.snapshot();
    let w2 = b2.snapshot();
    let meta = |plan: &str, seq: u64| SnapshotMeta {
        plan_id: plan.into(),
        sequence: seq,
        time: Timestamp { seconds: 1_793_675_400, nanos: 0 },
        phase: "steady".into(),
        is_final: false,
    };
    let snaps = vec![
        json!({"agent": "agent-a", "snapshot": agg_a.to_proto_json(&meta("run-1/agent-a", 3)).unwrap()}),
        json!({"agent": "agent-b", "snapshot": w1.to_proto_json(&meta("run-1/agent-b", 5)).unwrap()}),
        json!({"agent": "agent-b", "snapshot": w2.to_proto_json(&meta("run-1/agent-b", 6)).unwrap()}),
    ];
    let merged = Snapshot::merge_all([&agg_a, &w1, &w2]).unwrap();
    let counters: Vec<Value> = merged
        .to_proto_json(&meta("run-1/merged", 1))
        .unwrap()
        .get("counters")
        .cloned()
        .unwrap_or(Value::Null)
        .as_array()
        .cloned()
        .unwrap_or_default();
    let out = json!({
        "comment": "Generated by fps-stats Snapshot::merge_all, the reference merge of CTL-08.",
        "snapshots": snaps,
        "merged": {
            "snapshot": merged.to_proto_json(&meta("run-1/merged", 1)).unwrap(),
            "counters": counters,
            "histograms": hist_json(&merged),
        },
    });
    println!("{}", serde_json::to_string_pretty(&out).unwrap());
}
